function showView(view,scroll=0){if(familyMode&&['parent','insights'].includes(view)&&session.role!=='parent'){toast('家长管理需要家长身份。');view='home';}if(!$(view))return;activeView=view;document.querySelectorAll('.view').forEach(el=>el.hidden=el.id!==view);document.querySelectorAll('.nav').forEach(el=>el.classList.toggle('active',(el.dataset.view===view||(view==='lesson'&&el.dataset.view==='home'))));$('breadcrumb').innerHTML='我的学习空间 <i>/</i> '+titles[view];if(view==='notebook')renderNotes();if(view==='review')renderReview();if(view==='insights'||view==='parent')renderReport();if(view==='knowledge')renderKnowledge();$('page-navigation').hidden=view==='home';$('page-back').textContent=history.state?.depth>0?'← 返回上一页':'← 返回学习桌';window.scrollTo(0,scroll);}
function go(view,{replace=false}={}){if(!$(view))return;if(view===activeView){showView(view);return;}const prev=history.state||{};history.replaceState({...prev,judyApp:true,view:activeView,scroll:window.scrollY},'',location.href);const next={judyApp:true,view,depth:replace?0:(prev.depth||0)+1,scroll:0};if(replace)history.replaceState(next,'','#'+view);else history.pushState(next,'','#'+view);showView(view);}
function backWithinApp(){if(history.state?.judyApp&&history.state.depth>0)history.back();else go('home',{replace:true});}

