function mode(photo){$('photo-panel').hidden=!photo;$('text-tab').classList.toggle('selected',!photo);$('photo-tab').classList.toggle('selected',photo);$('text-tab').setAttribute('aria-selected',String(!photo));$('photo-tab').setAttribute('aria-selected',String(photo));}
$('text-tab').onclick=()=>mode(false);$('photo-tab').onclick=()=>mode(true);
function selectSample(id){selected=samples.find(s=>s.id===id);if(!selected)return;$('question').value=selected.question;$('attempt').value=selected.attempt;tagOverride=false;renderTopicSuggestions();go('home');$('question').scrollIntoView({behavior:'smooth',block:'center'});toast('已载入合成样题；核对题目后进入讲解。');}
function clearPhoto(){knownUploadedSample=false;if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl=null;uploaded=null;$('image-wrap').hidden=true;$('photo').value='';$('camera').value='';$('ocr-result').textContent='';updateRecognitionButton();}
async function onFile(file){clearPhoto();if(!file)return;if(file.size>5*1024*1024)return toast('图片超过 5 MB，请裁剪或缩小后重试。');if(!['image/jpeg','image/png','image/webp'].includes(file.type))return toast('暂不支持此图片格式，请使用 JPG、PNG 或 WEBP。');uploaded=file;objectUrl=URL.createObjectURL(file);$('image-preview').src=objectUrl;$('image-wrap').hidden=false;selected=null;$('ocr-result').textContent='图片仅在本页预览。';await refreshRecognitionAvailability();}
$('photo').onchange=e=>onFile(e.target.files[0]);$('camera').onchange=e=>onFile(e.target.files[0]);$('take-photo').onclick=()=>$('camera').click();$('remove-photo').onclick=clearPhoto;
async function sha(bytes){return [...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(x=>x.toString(16).padStart(2,'0')).join('');}
function download(blob,name){const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
async function samplePng(){const s=selected||samples[0];const c=document.createElement('canvas');c.width=1200;c.height=600;const ctx=c.getContext('2d');ctx.fillStyle='#fffef7';ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle='#36543e';ctx.font='30px sans-serif';ctx.fillText('Judy Math AI · 合成测试题（非学生数据）',55,65);ctx.font='36px sans-serif';let line='',y=145;for(const ch of s.question){if(ctx.measureText(line+ch).width>1080){ctx.fillText(line,55,y);line=ch;y+=65;}else line+=ch;}if(line)ctx.fillText(line,55,y);ctx.font='25px sans-serif';ctx.fillStyle='#8c9c7d';ctx.fillText('测试图片匹配 → 核对题干 → 分步讲解',55,540);const blob=await new Promise(r=>c.toBlob(r,'image/png'));sampleHashes.set(await sha(await blob.arrayBuffer()),s.id);return {blob,s};}
$('download-sample').onclick=async()=>{const {blob,s}=await samplePng();download(blob,'judy-synthetic-'+s.id+'.png');toast('下载完成后，可在本页选择这张图片测试识题流程。');};
async function api(path,data){const resp=await fetch('/api/'+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const text=await resp.text();let val;try{val=JSON.parse(text);}catch{throw new Error('当前预览未启用服务端 AI；可使用合成样题或手工录入。');}if(familyMode&&resp.status===401)location.assign('/family-login');if(!resp.ok)throw new Error(val.message||'服务暂时不可用');return val;}
function asData(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('图片读取失败，请重新选择。'));r.readAsDataURL(file);});}
$('recognize').onclick=async()=>{if(!uploaded)return toast('先选择一张图片。');const btn=$('recognize');btn.disabled=true;$('ocr-result').textContent='正在检查图片…';try{const id=sampleHashes.get(await sha(await uploaded.arrayBuffer()));if(id){selected=samples.find(s=>s.id===id);$('question').value=selected.question;$('attempt').value=selected.attempt;tagOverride=false;renderTopicSuggestions();$('ocr-result').innerHTML='<div class="confirm-box"><h3>已匹配已知合成测试图片</h3><p>这是预设图片的精确匹配，非真实 OCR。题干已填入下方，请逐字核对后开始学习。</p></div>';}else{if(!session.aiEnabled)throw new Error('网站的图片识别服务尚未开通，需要家长配置模型服务并验证家庭权限。重拍或换图片无法解决这个后台问题。');const data=await api('recognize',{image:await asData(uploaded)});if(!data.problems?.length)throw new Error(data.message||'未能辨认完整题目，请手工录入并确认。');$('ocr-result').innerHTML='<div class="confirm-box"><h3>选择要讲解的题目</h3>'+data.problems.map((p,i)=>'<button type="button" class="secondary ocr-choice" data-index="'+i+'">'+(i+1)+'. '+esc(p.text.slice(0,75))+(p.uncertain?'（需核对）':'')+'</button>').join('')+'</div>';$('ocr-result').querySelectorAll('.ocr-choice').forEach(b=>b.onclick=()=>{$('question').value=data.problems[Number(b.dataset.index)].text;selected=null;tagOverride=false;renderTopicSuggestions();toast('已填入题目，请核对所有数字和条件。');});}}catch(err){$('ocr-result').innerHTML='<div class="confirm-box"><h3>暂时无法自动识题</h3><p>'+esc(err.message)+'</p><button class="secondary" id="manual-entry">改为手工录入 ↓</button></div>';$('manual-entry').onclick=()=>{$('question').focus();$('question').scrollIntoView({behavior:'smooth',block:'center'});};}finally{updateRecognitionButton();}};
$('question-form').onsubmit=e=>{e.preventDefault();const q=$('question').value.trim();if(!q)return toast('请先填入完整题目，或选择一道合成样题。');if(!selected&&!session.realDataEnabled){toast('真实数据功能未启用；请仅录入自编的合成题目。');}pendingDraft={question:q,attempt:$('attempt').value.trim(),edition:$('edition').value,grade:$('grade').value,learningProfile:store.settings,knowledgeTags:[...chosenTags]};$('confirm-text').value=q;$('confirm-source').textContent=selected&&selected.question===q?'来源：已标注的原创合成样题。':'来源：手工录入或图片识题；请确认不是缺条件的题目。';open('confirm-dialog');};
$('confirm-cancel').onclick=()=>$('confirm-dialog').close();
$('confirm-start').onclick=async()=>{const q=$('confirm-text').value.trim();if(!q)return toast('题目不能为空。');pendingDraft.question=q;$('question').value=q;renderTopicSuggestions();pendingDraft.knowledgeTags=[...chosenTags];$('confirm-dialog').close();if(selected&&selected.question===q){current=structuredClone(selected);current.attempt=pendingDraft.attempt;current.knowledgeTags=[...chosenTags];chat=[];renderLesson();current.learningProfile=normalizeProfile(store.settings);event('lesson',current.id);persist();go('lesson');}else{const btn=$('question-form').querySelector('[type=submit]');btn.disabled=true;try{const data=await api('teach',{...pendingDraft,confirmed:true});current=data.lesson;current.learningProfile=normalizeProfile(store.settings);current.knowledgeTags=[...chosenTags];current.attempt=pendingDraft.attempt;current.knowledgeTags=[...chosenTags];chat=[];renderLesson();go('lesson');}catch(err){toast(err.message);buildPrompt();open('prompt-dialog');}finally{btn.disabled=false;}}};
function renderLesson(){focusedStep=null;if(!current){$('lesson-body').innerHTML=empty('先从一道题开始','回到学习桌，选择合成样题或核对题目。');return;}const s=current;const existing=store.notes.find(n=>n.sampleId===s.id);
 $('lesson-body').innerHTML='<div class="trial-banner">'+(s.live?'AI 讲解 · 请核对条件与计算；不确定的图形应再次确认。':'原创合成样题 · 下方讲解与追问提示为预设教学内容，不是实时 AI 分析。')+'</div><div class="lesson-layout"><div class="lesson-content"><section class="card" id="stage-0"><span class="sample-tag">'+(s.live?'模型生成，需核对':'合成样题')+'</span><span class="lesson-topic"> '+esc(s.topic)+'</span><h2>'+esc(s.question)+'</h2><div class="student-work">我的思路：'+esc(s.attempt||'还没有填写，可以在追问中说说你的想法。')+'</div><h3 style="margin-top:22px">Judy，我们先把关系看清楚。</h3><p><strong>已知：</strong>'+esc(s.known)+'</p><p><strong>要求：</strong>'+esc(s.ask)+'</p>'+(s.diagram?'<div class="diagram">'+graph(s.diagram)+'</div>':'<p class="field-note">此题暂未生成可验证的图解，先核对条件；不要根据猜测画图。</p>')+'<p><strong>用到的知识：</strong>'+esc(s.principle)+'</p></section><section id="stage-1" class="card" style="margin-top:16px"><span class="eyebrow">先给自己一点思考时间</span><h3>有一点卡住？看看提示。</h3>'+s.hints.map((h,i)=>'<details><summary>提示 '+(i+1)+' · '+(i?'再往前想一步':'从哪里开始？')+'</summary><p>'+esc(h)+'</p></details>').join('')+'</section><section id="stage-2" class="card" style="margin-top:16px"><h3>一步一步讲清楚。</h3><details id="full-solution"><summary>我思考过了，展开分步解答与检验</summary>'+lessonSteps(s).map(step=>'<article class="solution-step" data-solution-step="'+step.index+'"><div class="solution-step-heading"><strong>第 '+(step.index+1)+' 步</strong><button type="button" class="step-help" data-step-help="'+step.index+'">这一步没懂</button></div><p>'+esc(step.text)+'</p>'+(step.reason?'<p class="step-reason"><strong>依据：</strong>'+esc(step.reason)+'</p>':'<p class="field-note">这份讲解尚未记录该步依据，可以点击追问。</p>')+'</article>').join('')+'<div class="hint-box"><span>结论</span><p>'+esc(s.answer)+'</p></div></details></section><section id="stage-3" class="card" style="margin-top:16px"><h3>知识点与方法总结</h3><p><strong>本题知识点：</strong>'+esc(s.topic)+'</p><p>'+esc(s.principle)+'</p><h4>同类题的通用方法</h4><ol>'+s.method.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ol><div class="hint-box"><span>关键句</span><p>'+esc(s.key)+'</p></div><p><strong>易错点：</strong>'+esc(s.error)+'</p><div class="lesson-actions"><button id="save-current" class="primary">'+(existing?'已加入 · 更新讲解记录':'加入我的错题本')+'</button><button id="print-current" class="secondary">生成 A4 学习卡</button></div></section><section id="stage-4" class="card" style="margin-top:16px"><span class="eyebrow">合上答案，独立试一试</span><h3>'+esc(s.variant)+'</h3><label for="variant-answer">我的数值答案：</label><input id="variant-answer" type="number" step="any" placeholder="先独立计算"><button id="check-variant" class="secondary">检查</button><p id="variant-result" role="status"></p></section><section id="stage-5" class="card" style="margin-top:16px"><h3>哪里还不明白？继续问老师。</h3><div id="ask-context" class="ask-context" hidden></div><div class="lesson-actions">'+['只给我提示','再简单讲一遍','为什么这样列式','换一种方法'].map(t=>'<button class="secondary quick-ask" data-ask="'+t+'">'+t+'</button>').join('')+'</div><div id="chat" class="chat" aria-live="polite"></div><form id="ask-form" class="ask-row"><input id="ask-input" maxlength="2000" placeholder="说说你不明白的地方…" aria-label="继续追问"><button class="primary" id="send-ask">问老师 →</button></form><p class="field-note">'+(s.live?'追问调用服务端 AI。':'合成模式仅支持与本题原理相关的预设回答；自由题目需接通 AI。')+'</p></section></div></div>';
 document.querySelectorAll('[data-anchor]').forEach(b=>b.onclick=()=>$(b.dataset.anchor).scrollIntoView({behavior:'smooth',block:'start'}));
 $('save-current').onclick=saveCurrent;$('print-current').onclick=()=>printCard(current);
 $('check-variant').onclick=()=>{const v=$('variant-answer').value;if(v==='')return toast('先写下你的答案。');const correct=Math.abs(Number(v)-s.variantAnswer)<1e-8;$('variant-result').textContent=correct?'答对了。'+s.variantExplain+' 请再用自己的话说说为什么。':'我们再检查一下数量关系和运算；先试着独立修改。';event(correct?'practice-correct':'practice-attempt',s.id);persist();};
 document.querySelectorAll('[data-step-help]').forEach(button=>button.onclick=()=>{focusedStep=Number(button.dataset.stepHelp);renderAskContext();$('stage-5').scrollIntoView({behavior:'smooth',block:'start'});ask('这一步没懂，请用更简单的话解释依据，再问我一个小问题。');});document.querySelectorAll('.quick-ask').forEach(b=>b.onclick=()=>ask(b.dataset.ask));$('ask-form').onsubmit=e=>{e.preventDefault();ask($('ask-input').value.trim());};const questionCard=$('stage-0');questionCard.insertAdjacentHTML('beforeend','<p class="field-note">'+esc(normalizeProfile(store.settings).grade)+' · 人教版初中三年 · '+(store.settings.textbookVerified?'教材描述由家长核对':'具体教材版次待核对')+'</p>');$('stage-1').after($('stage-5'));const courseBox=document.createElement('section');courseBox.className='card course-panel';courseBox.id='lesson-courses';courseBox.innerHTML='<details><summary>补学：对应知识与官方课程</summary>'+resourceMarkup(s)+'</details>';document.querySelector('.lesson-content').append(courseBox);bindCourseButtons(courseBox,s);renderChat();math($('lesson-body'));
}
function renderAskContext(){const box=$('ask-context');if(!box)return;const focus=stepContext(current,focusedStep);box.hidden=!focus;if(!focus){box.replaceChildren();return;}box.innerHTML='<div><strong>正在追问：第 '+(focus.index+1)+' 步</strong><p>'+esc(focus.text)+'</p></div><button id="clear-step-context" type="button" class="text-button">改问整道题 ×</button>';$('clear-step-context').onclick=()=>{focusedStep=null;renderAskContext();$('ask-input').focus();};}
function renderChat(){if(!$('chat'))return;$('chat').innerHTML=chat.map(m=>'<div class="message '+(m.role==='user'?'student':'')+'"><small>'+(m.role==='user'?'我的问题':current.live?'AI 老师':'合成示例 · 老师提示')+(Number.isInteger(m.stepIndex)?' · 第 '+(m.stepIndex+1)+' 步':'')+'</small>'+esc(m.content)+'</div>').join('');math($('chat'));$('chat').scrollTop=$('chat').scrollHeight;}
async function ask(text){if(!text||!current)return;if(asking)return toast('老师正在解释上一条问题，请稍等。');asking=true;const lesson=current,conversation=chat,focus=stepContext(lesson,focusedStep),history=conversation.slice(-16).map(m=>({role:m.role,content:m.content}));const content=focus?'关于第 '+(focus.index+1)+' 步：'+text:text;conversation.push({role:'user',content,...(focus?{stepIndex:focus.index}:{})});$('ask-input').value='';renderChat();document.querySelectorAll('#send-ask,.quick-ask,[data-step-help]').forEach(b=>b.disabled=true);let reply;
 try{if(lesson.live){reply=(await api('followup',{question:lesson.question,attempt:lesson.attempt||'',message:content,history,learningProfile:lesson.learningProfile||store.settings,...(focus?{focusStep:focus}:{})})).reply;}else if(focus){reply=sampleStepReply(lesson,focus.index);}else if(/提示/.test(text))reply='先只想这一步：'+lesson.hints[0];else if(/换|另一|方法/.test(text))reply=lesson.alternate;else if(/为什么|列式|原理/.test(text))reply=lesson.why;else if(/简单|不懂|不会|什么意思/.test(text))reply='Judy，我们先不急着算。'+lesson.known+' 想一想：'+lesson.ask+' 记住：'+lesson.key;else reply='这段是合成教学演示，暂不能理解所有自由追问。你可以选择不理解的那一步，或试试“为什么这样列式”“再简单讲一遍”。自由解答需要接通 AI。';conversation.push({role:'assistant',content:reply,...(focus?{stepIndex:focus.index}:{})});}
 catch(error){conversation.push({role:'assistant',content:'本次追问未成功：'+error.message,...(focus?{stepIndex:focus.index}:{})});}
 finally{const note=store.notes.find(n=>n.sampleId===lesson.id);if(note){note.chat=structuredClone(conversation);persist();}asking=false;if(current===lesson&&chat===conversation){renderChat();document.querySelectorAll('#send-ask,.quick-ask,[data-step-help]').forEach(b=>b.disabled=false);}}
}

function saveCurrent(){if(!current)return;let n=store.notes.find(n=>n.sampleId===current.id);if(n){n.lesson=structuredClone(current);n.chat=structuredClone(chat);n.attempt=current.attempt||'';n.knowledgeTags=current.knowledgeTags||n.knowledgeTags||[];n.updatedAt=new Date().toISOString();}else{n={id:crypto.randomUUID(),sampleId:current.id,question:current.question,attempt:current.attempt||'',lesson:structuredClone(current),chat:structuredClone(chat),createdAt:new Date().toISOString(),nextReview:new Date(Date.now()+864e5).toISOString(),reviews:0,state:'待复习',cause:'尚未归因',reflection:'',answer:current.steps.join('\n'),synthetic:!current.live,knowledgeTags:current.knowledgeTags||inferTopics(current).map(t=>t.name)};store.notes.unshift(n);event('save',n.id);}if(persist()){toast('已保存讲解与问答；明天回来独立重做。');$('save-current').textContent='已加入 · 更新讲解记录';renderRecent();}}
function date(s){return new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'numeric',day:'numeric'}).format(new Date(s));}
function renderRecent(){$('note-count').textContent=store.notes.length;$('recent').innerHTML=store.notes.length?store.notes.slice(0,3).map(n=>'<button class="mini-note" data-learn="'+n.id+'"><span class="sample-tag">'+(n.synthetic?'合成':'已核对')+'</span> '+esc(n.lesson?.name||n.lesson?.topic||'自编题目')+'<br>'+esc(n.question.slice(0,40))+'…<br><small>'+date(n.createdAt)+' · '+esc(n.state)+'</small></button>').join(''):'<p class="field-note">还没有记录。先体验一道合成样题，再把方法存下来。</p>';}
function renderNotes(){renderRecent();const q=$('search').value.trim(),filter=$('filter-subject').value;const ns=store.notes.filter(n=>(!q||(n.question+' '+n.reflection+' '+n.cause+' '+(n.knowledgeTags||[]).join(' ')).includes(q))&&(filter==='全部题型'||filter===n.lesson?.name||(n.knowledgeTags||[]).includes(filter)));$('notes-list').innerHTML=ns.length?ns.map(n=>'<article class="note-item"><div><span class="sample-tag">'+(n.synthetic?'合成试用':'模型讲解')+'</span> <span class="note-tag">'+esc(n.lesson?.topic||'待归类')+'</span><h3>'+esc(n.question)+'</h3><div class="note-tags-display">'+(n.knowledgeTags||[]).map(t=>'<span class="note-tag">'+esc(t)+'</span>').join('')+'</div><p>'+date(n.createdAt)+' · 复习 '+n.reviews+' 次 · '+esc(n.cause)+' · <span class="badge-state">'+esc(n.state)+'</span></p>'+(n.reflection?'<p>我的总结：'+esc(n.reflection)+'</p>':'')+'</div><div class="actions"><button class="secondary" data-open="'+n.id+'">编辑与反思</button><button class="primary" data-learn="'+n.id+'">重新学习</button><button class="secondary" data-courses="'+n.id+'">对应知识与课程 ↗</button></div></article>').join(''):empty(store.notes.length?'没有找到相符题目':'错题本，等你写下第一份收获。','可以按题目、反思或错因搜索。');}
$('search').oninput=renderNotes;$('filter-subject').onchange=renderNotes;
function openNote(id){editing=store.notes.find(n=>n.id===id);if(!editing)return;$('detail-title').textContent=editing.question;$('detail-attempt').textContent='我的思路：'+(editing.attempt||'未填写');$('cause').value=editing.cause;$('reflection').value=editing.reflection;$('teacher-answer').value=editing.answer;renderNoteTagEditor(editing);open('note-dialog');}
$('save-reflection').onclick=()=>{if(!editing)return;editing.knowledgeTags=readTagEditor();editing.cause=$('cause').value;editing.reflection=$('reflection').value;editing.answer=$('teacher-answer').value;editing.updatedAt=new Date().toISOString();if(persist()){$('note-dialog').close();renderNotes();toast('反思已保存。');}};
$('delete-note').onclick=async()=>{if(familyMode&&!await requireFamilyParent())return;if(!editing)return;if(!confirm('确定删除这道题、问答和复习记录？此操作无法撤销，请先导出备份。'))return;const id=editing.id;store.notes=store.notes.filter(n=>n.id!==id);store.events=store.events.filter(e=>e.noteId!==id);if(persist()){$('note-dialog').close();renderNotes();toast('已删除这道题。');}};
function relearn(id){const n=store.notes.find(n=>n.id===id);if(!n)return;if(n.pending){selected=null;$('question').value=n.question;$('attempt').value=n.attempt;chosenTags=new Set(n.knowledgeTags||[]);tagOverride=true;renderTopicSuggestions();go('home');toast('这道题尚未生成讲解，可核对题目后继续。');return;}current=structuredClone(n.lesson);current.attempt=n.attempt;current.knowledgeTags=n.knowledgeTags||[];chat=structuredClone(n.chat||[]);renderLesson();go('lesson');}
function renderReview(){const ns=store.notes.filter(n=>!n.pending).slice().sort((a,b)=>a.nextReview.localeCompare(b.nextReview));$('review-list').innerHTML=ns.length?ns.map(n=>'<article class="note-item"><div><span class="note-tag">'+(new Date(n.nextReview)<=new Date()?'今天待复习':'计划 '+date(n.nextReview))+'</span><span class="sample-tag">'+(n.synthetic?'合成试用':'核对后的题目')+'</span><h3>'+esc(n.question)+'</h3><div class="note-tags-display">'+(n.knowledgeTags||[]).map(t=>'<span class="note-tag">'+esc(t)+'</span>').join('')+'</div><p>已复习 '+n.reviews+' 次 · '+esc(n.state)+' · 合上答案，先独立做一遍。</p></div><div class="actions"><button class="secondary" data-learn="'+n.id+'">独立重做 / 核对</button><button class="primary" data-reviewed="'+n.id+'">记录本次复习</button></div></article>').join(''):empty('今天，先弄懂一道新题吧。','完成讲解并保存后，根据每次复习反馈安排下一次。');}
function reviewed(id){const n=store.notes.find(n=>n.id===id);if(!n)return;openReview(n);}
function openReview(n){if(n.pending)return toast('这道题还在等待讲解，先学习并核对后再安排复习。');let dialog=$('review-dialog');if(!dialog){document.body.insertAdjacentHTML('beforeend','<dialog id="review-dialog"><div class="dialog-top"><span class="eyebrow">独立重做后再评价</span><button class="close" aria-label="关闭">×</button></div><h2>这次做起来怎么样？</h2><p>根据你的反馈安排下次复习。自评不等于系统已验证掌握。</p><div class="rating-options"><button id="review-again" class="secondary">还不会</button><button id="review-hard" class="secondary">比较吃力</button><button id="review-independent" class="primary">能独立完成</button><button id="review-easy" class="secondary">轻松并能讲明白</button></div><p class="field-note">间隔复习由 FSRS 排期，已学理解仍需用过程、检验与变式来检查。</p></dialog>');dialog=$('review-dialog');}
 const finish=rating=>{let result;try{result=nextReview(n.reviewCard,rating);}catch{toast('复习排期数据需要检查，未修改记录。请先导出备份。');return;}n.reviewCard=result.card;n.reviewAlgorithm=result.algorithm;n.reviewLog=Array.isArray(n.reviewLog)?n.reviewLog:[];n.reviewLog.push({rating,at:new Date().toISOString(),due:result.due});if(n.reviewLog.length>100)n.reviewLog=n.reviewLog.slice(-100);n.reviews++;const independent=rating==='good'||rating==='easy';n.state=independent?'自评可独立完成':'仍需巩固';n.nextReview=result.due;event(independent?'review-independent':'review-help',n.id);if(persist()){dialog.close();renderReview();toast('已记录反馈，下次复习为 '+date(n.nextReview)+'。');}};$('review-again').onclick=()=>finish('again');$('review-hard').onclick=()=>finish('hard');$('review-independent').onclick=()=>finish('good');$('review-easy').onclick=()=>finish('easy');dialog.showModal();}

function renderKnowledge(){$('knowledge-list').innerHTML='<section class="card knowledge-overview"><h3>初中三年知识点 · '+topicRules.length+' 类候选内容</h3><p>七至九年级候选框架，按教材与进度核对；不代表已经接入题库或完成所有题型。</p>'+topicNavigationMarkup()+'<div id="my-topic-summary"></div></section>'+samples.map(s=>'<section class="card knowledge-card"><span class="eyebrow">'+esc(s.chapter)+' · 原创合成样题</span><h3>'+esc(s.name)+' · 五步方法卡</h3><p>'+esc(s.key)+'</p><div class="diagram">'+graph(s.diagram)+'</div><ol>'+s.method.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ol><div class="lesson-actions"><button class="primary" data-card="'+s.id+'">A4 打印 / 存为 PDF</button><button class="secondary" data-sample="'+s.id+'">学习这道题</button><button class="secondary" data-courses="sample:'+s.id+'">对应课程 ↗</button></div></section>').join('');renderMyTopics();}
function printCard(s){if(!s)return;const root=$('print-root');root.innerHTML='<div class="print-label">JUDY MATH AI · 七年级数学 · '+(s.live?'AI生成，已核对题目仍需复核':'原创合成样题')+'</div><h1>'+esc(s.name||s.topic)+' · 五步学习卡</h1><div class="print-meta">关键知识：'+esc(s.topic)+'　｜　教材描述由学习设置提供；具体章次需核对</div>'+(s.diagram?'<div class="diagram">'+graph(s.diagram)+'</div>':'')+'<div class="print-key"><strong>必须记住：</strong>'+esc(s.key)+'</div><div class="print-columns"><section><h2>五步通用模板</h2><ol>'+s.method.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ol><h2>常见错误</h2><p>'+esc(s.error)+'</p></section><section><h2>典型例题</h2><p>'+esc(s.question)+'</p><h2>关系、列式与检验</h2>'+s.steps.map(x=>'<p>'+esc(x)+'</p>').join('')+'</section></div><section><h2>独立再练一道</h2><p>'+esc(s.variant)+'</p><p>我的关系式：________________________________________</p><p>我的检验：__________________________________________</p></section><div class="print-footer">先画图找数量关系 → 再列式 → 最后检验。Judy Math AI · 家庭学习使用 · 原创内容，未导入第三方知识图谱。</div>';math(root);window.print();}
function stats(){const now=Date.now(),last=now-7*864e5;const events=store.events.filter(e=>Date.parse(e.at)>=last);return {saved:store.notes.filter(n=>Date.parse(n.createdAt)>=last).length,reviews:events.filter(e=>e.type.startsWith('review-')).length,due:store.notes.filter(n=>!n.pending&&Date.parse(n.nextReview)<=now).length,practice:events.filter(e=>e.type==='practice-correct').length,events};}
function renderReport(){const x=stats();$('stats').innerHTML=[['已保存题目',store.notes.length,'本机记录'],['近7天复习',x.reviews,'有明确复习操作'],['到期待复习',x.due,'按复习计划计算'],['变式答对次数',x.practice,'次数不等于掌握人数']].map(([label,n,small])=>'<div class="stat">'+label+'<b>'+n+'</b><small>'+small+'</small></div>').join('');const causes={};store.notes.forEach(n=>{if(n.cause!=='尚未归因')causes[n.cause]=(causes[n.cause]||0)+1;});const entries=Object.entries(causes).sort((a,b)=>b[1]-a[1]);const topics={};store.notes.filter(n=>n.state==='仍需巩固').forEach(n=>{const k=n.lesson?.topic||'未归类';topics[k]=(topics[k]||0)+1;});const summary=store.notes.length?'<p>近 7 天新保存 '+x.saved+' 道题，记录复习 '+x.reviews+' 次；当前 '+x.due+' 道题到期。所有数据来自此浏览器的试用操作。</p><h3>已记录的错因</h3>'+(entries.length?entries.map(([k,v])=>'<p>'+esc(k)+' · '+v+' 道</p><div class="report-bar"><span style="width:'+Math.round(v/store.notes.length*100)+'%"></span></div>').join(''):'<p>还没有标记错因。先在错题本写下一句“我为什么会错”。</p>')+'<h3>下一周的建议</h3><p>'+(Object.keys(topics).length?'优先重做你自评仍需巩固的题目：'+esc(Object.keys(topics).join('、'))+'。':'先按复习计划独立重做，再标记是否需要帮助。暂没有足够记录判断薄弱知识点。')+'</p>':'<p>暂无学习记录，暂不能判断薄弱点或给出个人化结论。先学习并保存一道合成题，再记录一次复习。</p>';$('summary').innerHTML=summary;
 $('parent-body').innerHTML='<div class="trial-banner">家长页面仅为合成模式预览。真实数据被服务端开关阻断；尚未完成真实家庭账号的端到端权限验证。</div><div class="parent-grid"><section class="card"><h3>近 7 天学习与复习</h3>'+summary+'</section><section class="card"><h3>系统与隐私状态</h3><ul class="checklist"><li>✓ 默认私人站点，未请求公开访问</li><li>✓ 原图默认不保存，仅在当前页预览</li><li>✓ API Key 仅由服务端读取</li><li>✓ 真实模型接口核验家庭账号与来源</li><li class="warning">○ 家庭账号与家长/学生隔离：待配置验证</li><li class="warning">○ AI 图片识别与自由讲题：'+(session.aiEnabled?'已配置，待实题验证':'未接通')+'</li><li class="warning">○ 多设备数据库同步与定时通知：未接通</li></ul><h3>学习设置</h3><p>年级：'+esc(store.settings.grade)+' · 教材：'+esc(store.settings.edition||'待家长确认')+'</p><button class="secondary" id="parent-settings">修改设置</button></section><section class="card"><h3>数据管理</h3><p>记录保存在本机浏览器，清除浏览器数据会丢失。JSON 备份包含完整讲解、问答与复习记录，不含照片。</p><div class="lesson-actions"><button class="primary" id="parent-export">导出备份</button><button class="secondary" id="import-data">导入备份</button><button class="danger" id="clear-data">删除本机全部记录</button></div><input id="import-file" type="file" accept="application/json" hidden><p class="field-note">此版本只允许合成数据备份；不应导入真实学生学习数据。</p></section><section class="card"><h3>服务选择与资料来源</h3><p>模型接口预留阿里云百炼（Qwen 视觉模型）与 OpenAI。北京家庭可先评估中国大陆服务的账户、费用和可访问性；本轮未实际调用。</p><p>托管由 Sites 提供；北京网络实测尚未进行。正式长期使用可迁移至家庭选定的国内托管环境。</p><p>cn-math-taxonomy：仅查阅 README，未导入数据。若教材确认后复用，将注明版本、来源与 CC BY-NC 4.0 署名。</p><a class="text-button" href="https://github.com/xiaoyang111222/cn-math-taxonomy" target="_blank" rel="noopener">查看参考仓库 ↗</a></section></div>';
 $('parent-body').insertAdjacentHTML('afterbegin','<div class="parent-shortcuts"><button class="primary" id="parent-profile">学习设置</button><button class="secondary" data-view="insights">学习报告</button><button class="secondary" data-view="knowledge">知识点与学习卡</button></div>');$('parent-profile').onclick=openSettings;$('parent-body').insertAdjacentHTML('beforeend',parentResourcesMarkup()+researchMarkup());bindParentResources();$('parent-settings').onclick=openSettings;$('parent-export').onclick=exportData;$('import-data').onclick=()=>$('import-file').click();$('import-file').onchange=e=>importData(e.target.files[0]);$('clear-data').onclick=async()=>{if(familyMode&&!await requireFamilyParent())return;if(!confirm('确定删除本机全部题目、问答和复习记录？无法撤销，建议先导出 JSON 备份。'))return;store.notes=[];store.events=[];if(persist()){renderReport();renderRecent();toast('本机学习记录已清空。');}};
}
async function exportData(){if(familyMode&&!await requireFamilyParent())return;download(new Blob([JSON.stringify({schema:1,exportedAt:new Date().toISOString(),...store},null,2)],{type:'application/json'}),'judy-math-synthetic-backup.json');}
$('export').onclick=exportData;
function validTags(tags){return tags===undefined||(Array.isArray(tags)&&tags.length<=8&&tags.every(t=>typeof t==='string'&&t.length>0&&t.length<=40));}
function validReviewData(raw){try{if(raw)restoreCard(raw);return true;}catch{return false;}}
function validNote(n){return n&&typeof n.id==='string'&&typeof n.question==='string'&&n.question.length<=6000&&n.synthetic===true&&typeof n.createdAt==='string'&&Number.isFinite(Date.parse(n.createdAt))&&typeof n.nextReview==='string'&&Number.isFinite(Date.parse(n.nextReview))&&Number.isInteger(n.reviews)&&n.reviews>=0&&typeof n.cause==='string'&&typeof n.reflection==='string'&&typeof n.answer==='string'&&typeof n.state==='string'&&(samples.some(s=>s.id===n.sampleId)||(n.pending===true&&typeof n.sampleId==='string'&&n.sampleId.startsWith('manual-')))&&validTags(n.knowledgeTags)&&validReviewData(n.reviewCard)&&Array.isArray(n.chat)&&n.chat.every(m=>['user','assistant'].includes(m.role)&&typeof m.content==='string'&&m.content.length<=15000);}
async function importData(file){if(!file)return;if(familyMode&&!await requireFamilyParent())return;if(file.size>2e6)return toast('备份超过 2 MB，未导入。');try{const v=JSON.parse(await file.text());if(v.schema!==1||!Array.isArray(v.notes)||v.notes.length>500||!v.notes.every(validNote))throw new Error('仅支持本版本导出的合成数据 JSON。');if(v.courses!==undefined&&(!Array.isArray(v.courses)||v.courses.length>300||!v.courses.every(c=>topicRules.some(t=>t.id===c.topicId)&&typeof c.title==='string'&&c.title.length<=120&&typeof c.edition==='string'&&c.edition.length<=40&&c.reviewedByParent===true&&validateCourseUrl(c.url))))throw new Error('课程收藏包含不支持或不安全的链接。');const existing=new Set(store.notes.map(n=>n.id));const add=v.notes.filter(n=>!existing.has(n.id));for(const n of add){n.lesson=n.pending?{id:n.sampleId,name:'待讲解题目',question:n.question,topic:(n.knowledgeTags||[]).join('、')||'待归类',pending:true}:structuredClone(samples.find(s=>s.id===n.sampleId));store.notes.push(n);}if(Array.isArray(v.events)){const keys=new Set(store.events.map(e=>e.type+'|'+e.noteId+'|'+e.at));for(const e of v.events.slice(0,3000))if(e&&typeof e.type==='string'&&['lesson','save','practice-correct','practice-attempt','review-independent','review-help'].includes(e.type)&&typeof e.noteId==='string'&&Number.isFinite(Date.parse(e.at))&&!keys.has(e.type+'|'+e.noteId+'|'+e.at)){store.events.push({type:e.type,noteId:e.noteId,at:e.at});keys.add(e.type+'|'+e.noteId+'|'+e.at);}}if(!Array.isArray(store.courses))store.courses=[];for(const c of v.courses||[])if(!store.courses.some(old=>old.url===c.url&&old.topicId===c.topicId&&old.edition===c.edition))store.courses.push({id:crypto.randomUUID(),topicId:c.topicId,title:c.title,edition:c.edition,url:c.url,reviewedByParent:true,createdAt:new Date().toISOString()});if(persist()){renderReport();renderRecent();toast('已合并 '+add.length+' 道合成错题及有效课程收藏，未覆盖现有记录。');}}catch(err){toast('导入失败：'+err.message);}}

function openSettings(){const p=normalizeProfile(store.settings);$('settings-grade').value=p.grade;$('settings-edition').value=p.edition;$('settings-verified').checked=p.textbookVerified;$('settings-semester').value=p.semester;$('settings-chapter').value=p.currentChapter;$('settings-goal').value=p.learningGoal;document.querySelectorAll('[data-covered-topic]').forEach(el=>el.checked=p.coveredTopics.includes(topicRules.find(t=>t.id===el.dataset.coveredTopic)?.name));open('settings-dialog');}
$('settings').onclick=()=>go('parent');$('mobile-profile').onclick=()=>go('parent');
$('save-settings').onclick=async()=>{if(familyMode&&!await requireFamilyParent())return;store.settings=normalizeProfile({grade:$('settings-grade').value,edition:$('settings-edition').value,textbookVerified:$('settings-verified').checked,semester:$('settings-semester').value,currentChapter:$('settings-chapter').value,learningGoal:$('settings-goal').value,coveredTopics:[...document.querySelectorAll('[data-covered-topic]:checked')].map(el=>topicRules.find(t=>t.id===el.dataset.coveredTopic)?.name).filter(Boolean)});if(persist()){$('grade').value=store.settings.grade;$('edition').value=store.settings.edition;$('profile-grade').textContent=store.settings.grade+' · 数学';$('settings-dialog').close();if(activeView==='parent')renderReport();toast('学习设置已保存，后续讲解按当前年级解释。');}};
function buildPrompt(){const d=pendingDraft||{question:$('question').value,attempt:$('attempt').value};$('prompt-output').value='请做一位有经验、耐心的北京初中数学老师。'+profileContext(store.settings)+'先给提示，等我思考后再展示完整解答。\n题目：'+d.question+'\n我的思路：'+(d.attempt||'还没有写出')+'\n讲解顺序：1.读题，列已知与所求；2.先画数轴、线段或数量关系图；3.解释知识点和每步依据；4.列式并检验；5.总结关键句、易错点和五步模板；6.给一道难度相近的变式。如果条件缺失，先问我，不要猜。\n请按当前年级解释，遇到“为什么”说明数学原理。';}
$('copy-prompt').onclick=async()=>{try{await navigator.clipboard.writeText($('prompt-output').value);toast('已复制，请在 ChatGPT 中粘贴；若有照片需要另外附上。');}catch{$('prompt-output').select();toast('浏览器未允许复制，请长按或使用复制快捷键。');}};
$('save-draft').textContent='仅保存题目与知识点';$('save-draft').onclick=savePendingQuestion;
