renderTopicSuggestions();
renderRecent();renderLesson();renderKnowledge();
updateRecognitionButton();
fetch('/api/session').then(r=>r.json()).then(s=>{session=s;refreshRecognitionAvailability();if(s.aiEnabled){$('connection-title').textContent='AI 服务已配置 · 题干须先核对';$('connection-detail').textContent='图片仅发送到家长配置的模型服务处理，原图默认不留存；讲解仍须核对。';}}).catch(()=>{});
const hash=location.hash.slice(1);const initial=titles[hash]?hash:'home';history.replaceState({judyApp:true,view:initial,depth:0,scroll:0},'','#'+initial);showView(initial);
window.addEventListener('popstate',e=>{const v=titles[e.state?.view]?e.state.view:(titles[location.hash.slice(1)]?location.hash.slice(1):'home');showView(v,e.state?.scroll||0);});
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(titles[v]&&v!==activeView)showView(v);});
if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
